import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import * as crypto from 'crypto';

interface AuditEntry {
  timestamp: string;
  action: string;
  user: string;
  details: Record<string, unknown>;
}

class AuditLogger {
  private readonly logDir: string;
  private readonly sessionId: string;
  private bufferFile: string;
  private readonly maxBufferSize: number = 4096;

  constructor(logDir?: string) {
    this.logDir = logDir || path.join(os.homedir(), '.cli-audit');
    this.sessionId = crypto.randomBytes(16).toString('hex');
    this.ensureLogDir();
    this.bufferFile = this.createBufferFile();
  }

  private ensureLogDir(): void {
    if (!fs.existsSync(this.logDir)) {
      fs.mkdirSync(this.logDir, { mode: 0o700, recursive: true });
    }
  }

  private createBufferFile(): string {
    const timestamp = Date.now();
    const nonce = crypto.randomBytes(8).toString('hex');
    const filename = `audit-buffer-${timestamp}-${nonce}.tmp`;
    const filepath = path.join(os.tmpdir(), filename);

    // Create file with restricted permissions
    const fd = fs.openSync(filepath, 'w', 0o600);
    fs.closeSync(fd);

    return filepath;
  }

  private rotateBufferFile(): string {
    const archiveName = `audit-${this.sessionId}-${Date.now()}.log`;
    const archivePath = path.join(this.logDir, archiveName);

    // Atomically move buffer to archive
    fs.renameSync(this.bufferFile, archivePath);
    fs.chmodSync(archivePath, 0o400);

    // Create new buffer
    this.bufferFile = this.createBufferFile();
    return archivePath;
  }

  public log(entry: AuditEntry): void {
    const line = JSON.stringify(entry) + '\n';
    fs.appendFileSync(this.bufferFile, line, { encoding: 'utf-8' });

    const stats = fs.statSync(this.bufferFile);
    if (stats.size >= this.maxBufferSize) {
      this.rotateBufferFile();
    }
  }

  public flush(): string {
    return this.rotateBufferFile();
  }

  public getBufferPath(): string {
    return this.bufferFile;
  }
}

class SecureExporter {
  private readonly outputDir: string;
  private readonly logger: AuditLogger;

  constructor(outputDir: string, logger: AuditLogger) {
    this.outputDir = path.resolve(outputDir);
    this.logger = logger;
  }

  public exportReport(data: Record<string, unknown>): string {
    const reportId = crypto.randomBytes(12).toString('hex');
    const tempName = `.report-${reportId}.tmp`;
    const finalName = `report-${reportId}.json`;

    // Write to temp file first, then atomic rename
    const tempPath = path.join(this.outputDir, tempName);
    const finalPath = path.join(this.outputDir, finalName);

    const content = JSON.stringify(data, null, 2);

    // Stage 1: write to staging area in tmpdir
    const stagingPath = this.stageContent(content, reportId);

    // Stage 2: validate staged content
    const staged = fs.readFileSync(stagingPath, 'utf-8');
    JSON.parse(staged); // validate JSON

    // Stage 3: move to final location
    fs.copyFileSync(stagingPath, tempPath);
    fs.renameSync(tempPath, finalPath);
    fs.unlinkSync(stagingPath);

    this.logger.log({
      timestamp: new Date().toISOString(),
      action: 'export_report',
      user: os.userInfo().username,
      details: { reportId, path: finalPath }
    });

    return finalPath;
  }

  private stageContent(content: string, id: string): string {
    const stagingDir = path.join(os.tmpdir(), 'cli-export-staging');

    if (!fs.existsSync(stagingDir)) {
      fs.mkdirSync(stagingDir, { mode: 0o700 });
    }

    const stagingFile = path.join(stagingDir, `stage-${id}.json`);

    // Check if staging dir has correct ownership
    const dirStats = fs.statSync(stagingDir);
    const currentUid = process.getuid ? process.getuid() : 0;

    if (dirStats.uid !== currentUid) {
      throw new Error('Staging directory ownership mismatch - possible symlink attack');
    }

    fs.writeFileSync(stagingFile, content, { mode: 0o600 });
    return stagingFile;
  }
}

// CLI entry point
function main(): void {
  const args = process.argv.slice(2);
  const command = args[0];

  const logger = new AuditLogger();

  logger.log({
    timestamp: new Date().toISOString(),
    action: 'cli_start',
    user: os.userInfo().username,
    details: { command, args: args.slice(1) }
  });

  switch (command) {
    case 'export': {
      const outputDir = args[1] || '.';
      const exporter = new SecureExporter(outputDir, logger);
      const reportPath = exporter.exportReport({
        generated: new Date().toISOString(),
        auditBuffer: logger.getBufferPath(),
        system: { platform: os.platform(), hostname: os.hostname() }
      });
      console.log(`Report exported: ${reportPath}`);
      break;
    }
    case 'flush': {
      const archivePath = logger.flush();
      console.log(`Audit log archived: ${archivePath}`);
      break;
    }
    default:
      console.error('Usage: cli-tool <export|flush> [options]');
      process.exit(1);
  }
}

main();
